sed -i '' 's/import { findingsData, entitiesData } from '"'"'@\/data'"'"';/import { FindingsService, EntityService } from '"'"'@\/services\/api'"'"';\nimport { useState, useEffect } from '"'"'react'"'"';/g' src/pages/Findings/index.tsx

sed -i '' 's/export const Findings = () => {/export const Findings = () => {\n  const [findingsData, setFindingsData] = useState<any[]>([]);\n  const [entitiesData, setEntitiesData] = useState<any[]>([]);\n\n  useEffect(() => {\n    const fetchData = async () => {\n      const [findings, entities] = await Promise.all([\n        FindingsService.getFindings(),\n        EntityService.getEntities()\n      ]);\n      setFindingsData(findings);\n      setEntitiesData(entities);\n    };\n    fetchData();\n  }, []);\n/g' src/pages/Findings/index.tsx
